1	/**
2	 * What MHPCO knows about the customer's standing: the facts of their history
3	 * with the office that its policy-wide discount rules are written against.
4	 */
5	export interface Customer {
6	  yearsWithMHPCO: number;
7	  /** Contracts this customer already holds, before the one being quoted. */
8	  previousContracts?: number;
9	}
10	
11	export interface Item {
12	  type: string;
13	  cursed?: boolean;
14	  enchantment?: number;
15	}
16	
17	/**
18	 * How MHPCO prices one insurable type. `kind` is the pricing category the
19	 * office files the type under: main items are priced one by one, components
20	 * are priced as a group so that the building-block offer can be applied.
21	 */
22	interface PriceListEntry {
23	  kind: "main" | "component";
24	  basePremium: number;
25	  insuranceValue: number;
26	}
27	
28	/**
29	 * The MHPCO price list: the office's record of every type it insures at all.
30	 * Absence from this list is the office's rejection condition — MHPCO insures
31	 * exactly what it has priced.
32	 */
33	const PRICE_LIST: Record<string, PriceListEntry> = {
34	  sword: { kind: "main", basePremium: 100, insuranceValue: 1000 },
35	  amulet: { kind: "main", basePremium: 60, insuranceValue: 600 },
36	  staff: { kind: "main", basePremium: 80, insuranceValue: 800 },
37	  potion: { kind: "main", basePremium: 40, insuranceValue: 400 },
38	  rune: { kind: "component", basePremium: 25, insuranceValue: 250 },
39	  moonstone: { kind: "component", basePremium: 25, insuranceValue: 250 },
40	};
41	const BLOCK_SIZE = 3;
42	const BLOCK_BASE_PREMIUM = 60;
43	const CURSE_SURCHARGE_RATE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
49	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
50	const PROCESSING_FEE = 5;
51	const DEDUCTIBLE_PER_DAMAGE = 100;
52	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
53	
54	/** MHPCO insures exactly the types on its price list; anything else it turns away. */
55	function priceListEntry(item: Item): PriceListEntry {
56	  const entry = PRICE_LIST[item.type];
57	  if (entry === undefined) {
58	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
59	  }
60	  return entry;
61	}
62	
63	function isComponent(item: Item): boolean {
64	  return priceListEntry(item).kind === "component";
65	}
66	
67	function isMainItem(item: Item): boolean {
68	  return priceListEntry(item).kind === "main";
69	}
70	
71	function itemBasePremium(item: Item): number {
72	  return priceListEntry(item).basePremium;
73	}
74	
75	/**
76	 * The building-block offer: MHPCO's standing promotion on a group of alike
77	 * components. It is a pricing offer, not a price-list fact, so it lives beside
78	 * the price list rather than inside it.
79	 */
80	function alikeGroupBasePremium(group: Item[]): number {
81	  return group.length === BLOCK_SIZE
82	    ? BLOCK_BASE_PREMIUM
83	    : group.reduce((total, component) => total + itemBasePremium(component), 0);
84	}
85	
86	/** Components are "alike" when they are of exactly the same type. */
87	function alikeKey(component: Item): string {
88	  return component.type;
89	}
90	
91	function componentsBasePremium(components: Item[]): number {
92	  const alikeGroups = new Map<string, Item[]>();
93	  for (const component of components) {
94	    const key = alikeKey(component);
95	    alikeGroups.set(key, [...(alikeGroups.get(key) ?? []), component]);
96	  }
97	  return [...alikeGroups.values()].reduce(
98	    (total, group) => total + alikeGroupBasePremium(group),
99	    0,
100	  );
101	}
102	
103	function curseSurcharge(item: Item): number {
104	  return item.cursed === true
105	    ? itemBasePremium(item) * CURSE_SURCHARGE_RATE
106	    : 0;
107	}
108	
109	function isHighlyEnchanted(item: Item): boolean {
110	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
111	}
112	
113	function highEnchantmentSurcharge(item: Item): number {
114	  return isHighlyEnchanted(item)
115	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
116	    : 0;
117	}
118	
119	/**
120	 * Item-specific modifiers apply to the base premium of the affected item and
121	 * are added to it, never multiplied onto it. Each risk rule is independent:
122	 * its own condition, its own rate.
123	 */
124	function itemSpecificModifiers(item: Item): number {
125	  return curseSurcharge(item) + highEnchantmentSurcharge(item);
126	}
127	
128	function mainItemsBasePremium(mainItems: Item[]): number {
129	  return mainItems.reduce((total, item) => total + itemBasePremium(item), 0);
130	}
131	
132	/** The policy base premium: the sum of all unmodified item base premiums. */
133	function policyBasePremiumFor(items: Item[]): number {
134	  return (
135	    mainItemsBasePremium(items.filter(isMainItem)) +
136	    componentsBasePremium(items.filter(isComponent))
137	  );
138	}
139	
140	/** The item-specific surcharges of every affected item, summed. */
141	function itemSpecificModifiersFor(items: Item[]): number {
142	  return items
143	    .filter(isMainItem)
144	    .reduce((total, item) => total + itemSpecificModifiers(item), 0);
145	}
146	
147	/**
148	 * Rounding in the MHPCO's favour is a single policy with two arms: an amount
149	 * the customer pays goes up, an amount MHPCO pays out goes down. This is the
150	 * premium arm; it is named for the amount it rounds so that a payout can never
151	 * reach it by mistake.
152	 */
153	function roundPremiumInMHPCOsFavour(premium: number): number {
154	  return Math.ceil(premium);
155	}
156	
157	/** Every item in a quote is treated as a first insurance. */
158	function firstInsuranceSurcharge(policyBasePremium: number): number {
159	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
160	}
161	
162	function isLongStanding(customer: Customer): boolean {
163	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
164	}
165	
166	function loyaltyDiscount(customer: Customer, policyBasePremium: number): number {
167	  return isLongStanding(customer)
168	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
169	    : 0;
170	}
171	
172	function isFollowUpContract(customer: Customer): boolean {
173	  return (customer.previousContracts ?? 0) > 0;
174	}
175	
176	function followUpDiscount(
177	  customer: Customer,
178	  policyBasePremium: number,
179	): number {
180	  return isFollowUpContract(customer)
181	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
182	    : 0;
183	}
184	
185	/**
186	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
187	 * base premiums) and are added to it, never multiplied onto it. Each rule is
188	 * independent: its own condition, its own rate. Surcharges raise the premium
189	 * and discounts lower it; each is computed as a positive amount off the
190	 * unmodified policy base premium and given its sign here.
191	 */
192	function policyWideModifiers(
193	  customer: Customer,
194	  policyBasePremium: number,
195	): number {
196	  return (
197	    firstInsuranceSurcharge(policyBasePremium) -
198	    loyaltyDiscount(customer, policyBasePremium) -
199	    followUpDiscount(customer, policyBasePremium)
200	  );
201	}
202	
203	export function quote(customer: Customer, items: Item[]): number {
204	  const policyBasePremium = policyBasePremiumFor(items);
205	  const premium =
206	    policyBasePremium +
207	    itemSpecificModifiersFor(items) +
208	    policyWideModifiers(customer, policyBasePremium) +
209	    PROCESSING_FEE;
210	  return roundPremiumInMHPCOsFavour(premium);
211	}
212	
213	export interface Damage {
214	  itemType: string;
215	  amount: number;
216	}
217	
218	export interface Incident {
219	  cause: string;
220	  damages: Damage[];
221	}
222	
223	export interface ClaimResult {
224	  payout: number;
225	  remainingCap: number;
226	}
227	
228	/** A policy MHPCO has written: the items it covers and the cap still available. */
229	export interface Policy {
230	  items: Item[];
231	  remainingCap: number;
232	}
233	
234	/** The insurance sum: what MHPCO insures the policy's items for, unmodified. */
235	function insuranceSumFor(items: Item[]): number {
236	  return items.reduce(
237	    (total, item) => total + priceListEntry(item).insuranceValue,
238	    0,
239	  );
240	}
241	
242	export function createPolicy(items: Item[]): Policy {
243	  return {
244	    items,
245	    remainingCap: insuranceSumFor(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
246	  };
247	}
248	
249	/** Rounded in MHPCO's favour: a payout of 350.5 G is settled at 350 G. */
250	function roundPayoutInMHPCOsFavour(payout: number): number {
251	  return Math.floor(payout);
252	}
253	
254	/** What one damage earns before the policy's cap is consulted. */
255	function reimbursementFor(damage: Damage): number {
256	  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
257	}
258	
259	/** What the incident earns on its own merits, cap not yet applied. */
260	function reimbursementForIncident(incident: Incident): number {
261	  return incident.damages.reduce(
262	    (total, damage) => total + reimbursementFor(damage),
263	    0,
264	  );
265	}
266	
267	/**
268	 * The settlement: what MHPCO actually pays. The office never pays more than
269	 * the cap still available on the policy, however much the damage earns.
270	 */
271	function settlementFor(policy: Policy, incident: Incident): number {
272	  return roundPayoutInMHPCOsFavour(
273	    Math.min(reimbursementForIncident(incident), policy.remainingCap),
274	  );
275	}
276	
277	/** Settling a claim pays the settlement and draws it down from the policy's cap. */
278	export function claim(policy: Policy, incident: Incident): ClaimResult {
279	  const payout = settlementFor(policy, incident);
280	  policy.remainingCap -= payout;
281	  return { payout, remainingCap: policy.remainingCap };
282	}
