2	import { claim, createPolicy, quote } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: processing fee and empty policy ---
6	  it("quotes an empty item list -- premium 5 G (processing fee only)", () => {
7	    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
8	  });
9	
10	  // --- Quote: base premiums per main item type ---
11	  it("quotes a single plain sword -- base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
12	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
13	  });
14	  it("quotes a single plain amulet -- base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
15	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
16	  });
17	  it("quotes a single plain staff -- base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
18	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(93);
19	  });
20	  it("quotes a single plain potion -- base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
21	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(49);
22	  });
23	
24	  // --- Quote: component base premiums and the building block ---
25	  it("quotes a single rune -- base 25 G component premium (25 + 2.5 + 5 -> 33 G)", () => {
26	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(33);
27	  });
28	  it("quotes a single moonstone -- base 25 G component premium (25 + 2.5 + 5 -> 33 G)", () => {
29	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }])).toBe(33);
30	  });
31	  it("quotes 2 runes -- base premium 50 G (no block) (50 + 5 + 5 = 60 G)", () => {
32	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(60);
33	  });
34	  it("quotes 3 runes -- base premium 60 G (block applies) (60 + 6 + 5 = 71 G)", () => {
35	    const runes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
36	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(71);
37	  });
38	  it("quotes 4 runes -- base premium 100 G (no block: block requires exactly 3) (100 + 10 + 5 = 115 G)", () => {
39	    const runes = Array.from({ length: 4 }, () => ({ type: "rune" }));
40	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(115);
41	  });
42	  it("quotes 7 runes -- base premium 175 G (no block: block requires exactly 3) (175 + 17.5 + 5 = 197.5 -> 198 G)", () => {
43	    const runes = Array.from({ length: 7 }, () => ({ type: "rune" }));
44	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(198);
45	  });
46	  it("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types) (75 + 7.5 + 5 = 87.5 -> 88 G)", () => {
47	    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
48	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(88);
49	  });
50	  it("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks) (120 + 12 + 5 = 137 G)", () => {
51	    const items = [
52	      ...Array.from({ length: 3 }, () => ({ type: "rune" })),
53	      ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
54	    ];
55	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(137);
56	  });
57	
58	  // --- Quote: item-specific modifiers ---
59	  it("adds a 50 % curse surcharge to the cursed item's base premium -- cursed sword 100 G -> 150 G (100 base + 50 curse + 10 first insurance + 5 fee = 165 G)", () => {
60	    const items = [{ type: "sword", cursed: true }];
61	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(165);
62	  });
63	  it("adds a 30 % high-enchantment surcharge at enchantment exactly 5 -- sword 100 G -> 130 G (100 + 30 + 10 + 5 = 145 G)", () => {
64	    const items = [{ type: "sword", enchantment: 5 }];
65	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(145);
66	  });
67	  it("adds no high-enchantment surcharge at enchantment 4 -- sword stays 100 G (100 + 10 + 5 = 115 G)", () => {
68	    const items = [{ type: "sword", enchantment: 4 }];
69	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(115);
70	  });
71	  it("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -- 100 G -> 180 G (100 + 50 + 30 + 10 + 5 = 195 G)", () => {
72	    const items = [{ type: "sword", enchantment: 5, cursed: true }];
73	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(195);
74	  });
75	
76	  // --- Quote: modifier scope on multi-item policies ---
77	  it("applies the curse surcharge only to the cursed item -- cursed sword + plain amulet -> 160 G base + 50 G = 210 G before further modifiers and fee (+16 first insurance + 5 fee = 231 G)", () => {
78	    const items = [
79	      { type: "sword", cursed: true },
80	      { type: "amulet", cursed: false },
81	    ];
82	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(231);
83	  });
84	
85	  // --- Quote: policy-wide modifiers ---
86	  it("applies the 10 % first insurance surcharge to every item in a quote regardless of customer history -- 3-year customer, plain sword: 100 + 10 first insurance - 20 loyalty + 5 fee = 95 G", () => {
87	    const items = [{ type: "sword" }];
88	    expect(quote({ yearsWithMHPCO: 3 }, items)).toBe(95);
89	  });
90	  it("applies the 20 % loyalty discount at exactly 2 years with MHPCO -- sword: 100 + 10 - 20 + 5 = 95 G", () => {
91	    expect(quote({ yearsWithMHPCO: 2 }, [{ type: "sword" }])).toBe(95);
92	  });
93	  it("applies no loyalty discount at 1 year with MHPCO -- sword: 100 + 10 + 5 = 115 G", () => {
94	    expect(quote({ yearsWithMHPCO: 1 }, [{ type: "sword" }])).toBe(115);
95	  });
96	  it("applies a 15 % follow-up discount on each contract after the customer's first -- second contract, plain sword: 100 + 10 - 15 + 5 = 100 G", () => {
97	    const customer = { yearsWithMHPCO: 0, previousContracts: 1 };
98	    expect(quote(customer, [{ type: "sword" }])).toBe(100);
99	  });
100	  it("applies no follow-up discount to the customer's first contract -- sword: 100 + 10 + 5 = 115 G", () => {
101	    expect(quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "sword" }])).toBe(115);
102	  });
103	  it("adds the 5 G processing fee at the very end of every premium -- 3-year customer, amulet: 60 + 6 - 12 = 54, + 5 fee = 59 G", () => {
104	    expect(quote({ yearsWithMHPCO: 3 }, [{ type: "amulet" }])).toBe(59);
105	  });
106	
107	  // --- Quote: rounding in the MHPCO's favor ---
108	  it("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)", () => {
109	    const runes = Array.from({ length: 7 }, () => ({ type: "rune" }));
110	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(198);
111	  });
112	  it("keeps intermediate amounts as fractions and rounds only the final premium -- 3-year customer, 1 rune: 25 + 2.5 - 5 = 22.5, + 5 fee = 27.5 -> 28 G", () => {
113	    expect(quote({ yearsWithMHPCO: 3 }, [{ type: "rune" }])).toBe(28);
114	  });
115	
116	  // --- Quote: integration examples ---
117	  it("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) -- premium 165 G", () => {
118	    const customer = { yearsWithMHPCO: 0, previousContracts: 0 };
119	    const items = [
120	      { type: "sword", material: "steel", enchantment: 3, cursed: true },
121	    ];
122	    expect(quote(customer, items)).toBe(165);
123	  });
124	  it("quotes a long-standing customer's second contract: cursed sword enchantment 7, 3 years -- premium 160 G", () => {
125	    const customer = { yearsWithMHPCO: 3, previousContracts: 1 };
126	    const items = [
127	      { type: "sword", material: "steel", enchantment: 7, cursed: true },
128	    ];
129	    expect(quote(customer, items)).toBe(160);
130	  });
131	
132	  // --- Quote: rejection ---
133	  // Observable contract chosen here: the domain rejects by throwing an Error
134	  // naming the unknown type. The CLI translates that into a non-zero exit and
135	  // a stderr description; the spec fixes the CLI behaviour, not the mechanism.
136	  it("rejects a quote containing an unknown item type (e.g. broomstick) -- throws an Error naming the type", () => {
137	    expect(() => quote({ yearsWithMHPCO: 0 }, [{ type: "broomstick" }])).toThrow(
138	      /broomstick/,
139	    );
140	  });
141	
142	  // --- Claim: insurance sum and cap ---
143	  it("caps a single-sword policy at 2000 G (twice the 1000 G insurance sum) -- 1500 G damage pays 1400 G, 600 G cap left", () => {
144	    const policy = createPolicy([{ type: "sword" }]);
145	    expect(claim(policy, { cause: "dragon", damages: [{ itemType: "sword", amount: 1500 }] })).toEqual({
146	      payout: 1400,
147	      remainingCap: 600,
148	    });
149	  });
150	  it("sums insurance values across items -- sword + amulet -> insurance sum 1600 G, cap 3200 G", () => {
151	    const policy = createPolicy([{ type: "sword" }, { type: "amulet" }]);
152	    const incident = {
153	      cause: "dragon",
154	      damages: [{ itemType: "sword", amount: 4000 }],
155	    };
156	    expect(claim(policy, incident)).toEqual({ payout: 3200, remainingCap: 0 });
157	  });
158	  it.todo("bases the cap on unmodified insurance values -- cursed sword (premium 165 G) -> cap 2000 G");
159	  it.todo("counts component insurance values at 250 G each -- sword + 3 runes -> insurance sum 1750 G (block affects premium only)");
160	  it.todo("counts two swords as insurance sum 2000 G, cap 4000 G");
161	
162	  // --- Claim: standard reimbursement and deductible ---
163	  it.todo("reimburses a regular steel sword (enchantment 3) damage of 500 G -- payout 400 G");
164	  it.todo("reimburses a rune damage of 200 G -- payout 100 G (no enchantment or material clause)");
165	  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");
166	  it.todo("treats each damages entry of the same item type as a separate damage with its own deductible -- two damaged swords");
167	
168	  // --- Claim: special clauses ---
169	  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 % -- dragon sword, damage 1000 G -> payout 400 G");
170	  it.todo("reimburses dragon-material damage fully -- dragon sword enchantment 5, damage 800 G -> payout 700 G");
171	  it.todo("lets the 50 % high-enchantment rule win over full dragon reimbursement -- dragon sword enchantment 9, damage 1000 G -> payout 400 G");
172	  it.todo("applies the high-enchantment clause alone to a steel sword enchantment 9, damage 1000 G -> payout 400 G");
173	
174	  // --- Claim: cap exhaustion across successive claims ---
175	  it.todo("pays 1400 G on a first 1500 G claim against a 2000 G cap -- remainingCap 600 G");
176	  it.todo("reduces a second 1500 G claim to the remaining cap -- payout 600 G, remainingCap 0 G");
177	
178	  // --- Claim: rounding in the MHPCO's favor ---
179	  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");
180	
181	  // --- Claim: rejection ---
182	  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero with stderr error");
183	  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero with stderr error");
184	  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- CLI exits non-zero with stderr error");
185	  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero with stderr error");
186	
187	  // --- CLI: scenario orchestration and JSON contract ---
188	  it.todo("reads a scenario from stdin and writes {results:[...]} to stdout in step order");
189	  it.todo("resolves a claim step's policy field to the zero-based index of the earlier quote step");
190	  it.todo("returns premium for quote results and payout + remainingCap for claim results");
191	});
