/**
 * What MHPCO's reimbursement clauses say a damage amount is worth, before the
 * deductible is kept back. With no special clause in force the office
 * reimburses the damage in full.
 */
function reimbursableAmountFor(damage: Damage): number {
  return damage.amount;
}

/**
 * What one damage earns before the policy's cap is consulted: the reimbursable
 * amount its clauses allow, less the deductible MHPCO keeps per damage event.
 */
function reimbursementFor(damage: Damage): number {
  return reimbursableAmountFor(damage) - DEDUCTIBLE_PER_DAMAGE;
}

